#!/usr/bin/env node
/**
 * Points impeccable (the design skill in .claude/skills/impeccable) at the Design OS context, so
 * both read the same truth. impeccable looks for PRODUCT.md and DESIGN.md in the project root,
 * then in `.agents/context/`; two symlinks there lead to the Design OS files:
 *
 *   .agents/context/DESIGN.md  -> product/design-system/DESIGN.md   (generated by npm run tokens:build)
 *   .agents/context/PRODUCT.md -> product/PRODUCT.md                 (written by the designos-product-md skill)
 *
 * It also records `buildPath: "code"` in `.impeccable/config.json` (prototypes are built in code,
 * never from generated image comps) and keeps a Design OS block at the top of each installed
 * impeccable SKILL.md, so impeccable writes product truth to product/PRODUCT.md and never runs its
 * own init. The block is re-applied on every run, so `npx impeccable update` cannot lose it.
 * Idempotent; a missing target leaves its link out.
 *
 *   npm run impeccable:context            what is linked and what is missing
 *   npm run -s impeccable:context -- --json
 */
import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

export const CONTEXT_DIR = '.agents/context'
export const LINKS = [
  { name: 'DESIGN.md', target: 'product/design-system/DESIGN.md', fix: 'npm run tokens:build' },
  { name: 'PRODUCT.md', target: 'product/PRODUCT.md', fix: '/design-os:product-vision (designos-product-md skill)' },
]
const CONFIG = '.impeccable/config.json'
export const SKILL_FILES = ['.claude/skills/impeccable/SKILL.md', '.github/skills/impeccable/SKILL.md', '.opencode/skills/impeccable/SKILL.md']
const BEGIN = '<!-- design-os:begin (managed by npm run impeccable:context) -->'
const END = '<!-- design-os:end -->'
export const SKILL_NOTE = `${BEGIN}
## Design OS

This project plans its product in Design OS. These rules come before the rest of this skill:

- **PRODUCT.md is \`product/PRODUCT.md\`** (read through \`.agents/context/PRODUCT.md\`). Never create or write a PRODUCT.md at the project root. When it is missing, or \`init\` or \`teach\` is asked for, follow \`.claude/skills/designos-product-md/SKILL.md\` instead of reference/init.md; it writes \`product/PRODUCT.md\` in the same format.
- **DESIGN.md is generated** from the design tokens (\`npm run tokens:build\` writes \`product/design-system/DESIGN.md\`). Never write it, also not through \`document\`; fix the token inputs in \`product/design-system/import/\` instead.
- **Code-led:** prototypes are built in code (\`buildPath: code\`), never from generated image comps.
- Comments from the preview arrive as a \`design-comment\` block: follow \`.claude/commands/design-os/comment.md\`.
${END}`

/** Puts the Design OS block right after the frontmatter of a SKILL.md, replacing an older one */
export function withSkillNote(text) {
  const start = text.indexOf(BEGIN)
  const end = text.indexOf(END)
  const clean = start >= 0 && end > start ? text.slice(0, start) + text.slice(end + END.length).replace(/^\n+/, '') : text
  const front = clean.match(/^---\n[\s\S]*?\n---\n+/)
  const at = front ? front[0].length : 0
  return `${clean.slice(0, at)}${SKILL_NOTE}\n\n${clean.slice(at)}`
}

function noteSkills(root) {
  return SKILL_FILES.filter((file) => fs.existsSync(path.join(root, file))).map((file) => {
    const full = path.join(root, file)
    const text = fs.readFileSync(full, 'utf8')
    const next = withSkillNote(text)
    if (next !== text) fs.writeFileSync(full, next)
    return file
  })
}

/** Creates the links and the config; returns what each link is now */
export function linkContext(root) {
  const dir = path.join(root, CONTEXT_DIR)
  const links = LINKS.map(({ name, target, fix }) => {
    const link = path.join(dir, name)
    const relative = path.relative(dir, path.join(root, target))
    let current = null
    try {
      current = fs.readlinkSync(link)
    } catch {
      // No link yet (or a plain file, which is left alone below)
    }
    if (!fs.existsSync(path.join(root, target))) {
      if (current !== null) fs.unlinkSync(link)
      return { name, target, status: 'missing', fix }
    }
    if (current === relative) return { name, target, status: 'linked' }
    if (current === null && fs.existsSync(link)) return { name, target, status: 'blocked', fix: `remove ${CONTEXT_DIR}/${name}, Design OS owns it` }
    fs.mkdirSync(dir, { recursive: true })
    if (current !== null) fs.unlinkSync(link)
    fs.symlinkSync(relative, link)
    return { name, target, status: 'linked' }
  })

  const configPath = path.join(root, CONFIG)
  let config = {}
  try {
    config = JSON.parse(fs.readFileSync(configPath, 'utf8'))
  } catch {
    // Missing or unreadable: start from the Design OS defaults
  }
  if (config.buildPath !== 'code') {
    fs.mkdirSync(path.dirname(configPath), { recursive: true })
    fs.writeFileSync(configPath, `${JSON.stringify({ ...config, buildPath: 'code' }, null, 2)}\n`)
  }
  return { links, config: CONFIG, skills: noteSkills(root) }
}

/** Vite plugin: links the context when the dev server starts, so the chat agent finds it */
export function impeccableContext() {
  return {
    name: 'designos-impeccable-context',
    apply: 'serve',
    configResolved(config) {
      try {
        linkContext(config.root)
      } catch (error) {
        config.logger.warn(`impeccable context: ${error.message}`)
      }
    },
  }
}

function main() {
  const result = linkContext(process.cwd())
  if (process.argv.includes('--json')) {
    console.log(JSON.stringify(result, null, 2))
    return
  }
  for (const l of result.links) {
    const line = l.status === 'linked' ? `${CONTEXT_DIR}/${l.name} -> ${l.target}` : `${CONTEXT_DIR}/${l.name}: ${l.status} (${l.target}) — ${l.fix}`
    console.log(line)
  }
  console.log(`${result.config}: buildPath code`)
  for (const file of result.skills) console.log(`${file}: Design OS block`)
}

if (process.argv[1] === fileURLToPath(import.meta.url)) main()
